use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn is_valid_move(c: char) -> bool {
    c == 'U' || c == 'R'
}

spec fn region_of(x: int, y: int) -> int {
    if x > y {
        1  // Region A
    } else if y > x {
        2  // Region B
    } else {
        0  // Border
    }
}

fn solve(n: i8, s: Vec<char>) -> (result: i8)
    requires
        n >= 0,
        s.len() == n as usize,
        forall |i: int| 0 <= i < s.len() ==> is_valid_move(s[i]),
    ensures
        0 <= result <= n,
        // Additional property: result counts transitions between regions A and B
{
    let mut x: i8 = 0;
    let mut y: i8 = 0;
    let mut count: i8 = 0;
    let mut current_region: i8 = 0;  // 0 = border, 1 = A (x > y), 2 = B (y > x)
    let mut idx: usize = 0;
    
    while idx < s.len()
        invariant
            idx <= s.len(),
            x >= 0,
            y >= 0,
            x as int <= idx as int,
            y as int <= idx as int,
            x as int + y as int == idx as int,
            count >= 0,
            count <= idx as i8,
            current_region == region_of(x as int, y as int),
        decreases s.len() - idx,
    {
        let move_char = s[idx];
        
        // Update position based on move
        if move_char == 'U' {
            y = y + 1;
        } else {  // move_char == 'R'
            x = x + 1;
        }
        
        let new_region = region_of(x as int, y as int);
        
        // Check if this is a transition between regions A and B
        // Transition occurs if:
        // 1. We're moving to a different region
        // 2. Both old and new regions are not border (0)
        if new_region != current_region && current_region != 0 && new_region != 0 {
            count = count + 1;
        }
        
        current_region = new_region;
        idx = idx + 1;
    }
    
    count
}

}
